//! The style groups of the editorial look: a neutral paper-and-ink palette that every chart can
//! wear, the neutral boxes, hairlines and masks of diagrams, and the monospace of their technical
//! text. See `docs/guides/diagram-design.md` for the values and why they are what they are.

/// The editorial palette: paper, ink and one accent, in light and dark. Light sits on two
/// classes so that it beats the palette of the root wherever it is declared; dark sits on three,
/// so that it beats the light one on a dark chart. The blueprint theme keeps its own palette.
///
/// The role tokens are neutral on purpose: a kind of box is told by its shape and its tag, not
/// by a color. Only `critical` keeps a red outline, `planned` and `deprecated` stay ink, and all
/// three keep their badge and their line pattern.
pub(super) const PALETTE: &str = ".chartlet-root.chartlet-look-editorial{--chartlet-text:#1d1c1a;--chartlet-muted:#4d4a44;--chartlet-grid:#d8d4ca;--chartlet-zero:#6b665c;--chartlet-accent:#0b6a88;--chartlet-background:#fcfbf8;--chartlet-color-1:#0b6a88;--chartlet-color-2:#a8431a;--chartlet-color-3:#6b665c;--chartlet-color-4:#1d1c1a;--chartlet-node:#f2efe8;--chartlet-lane:#fcfbf8;--chartlet-lane-head:#f2efe8;--chartlet-shadow:rgba(0,0,0,0);--chartlet-role-blue:#6b665c;--chartlet-role-blue-fill:#f2efe8;--chartlet-role-green:#6b665c;--chartlet-role-green-fill:#f2efe8;--chartlet-role-amber:#6b665c;--chartlet-role-amber-fill:#f2efe8;--chartlet-role-teal:#6b665c;--chartlet-role-teal-fill:#f2efe8;--chartlet-role-violet:#4d4a44;--chartlet-role-violet-fill:#f2efe8;--chartlet-role-gray:#6b665c;--chartlet-role-gray-fill:#f2efe8;--chartlet-role-red:#a8281c;--chartlet-role-red-fill:#fbefec}.chartlet-root.chartlet-look-editorial.chartlet-theme-dark:not(.chartlet-blueprint){--chartlet-text:#ece8df;--chartlet-muted:#b7b2a7;--chartlet-grid:#3a3840;--chartlet-zero:#8f8a80;--chartlet-accent:#62b8d4;--chartlet-background:#17161a;--chartlet-color-1:#62b8d4;--chartlet-color-2:#e0916a;--chartlet-color-3:#9a958a;--chartlet-color-4:#ece8df;--chartlet-node:#222127;--chartlet-lane:#17161a;--chartlet-lane-head:#222127;--chartlet-shadow:rgba(0,0,0,0);--chartlet-role-blue:#8f8a80;--chartlet-role-blue-fill:#222127;--chartlet-role-green:#8f8a80;--chartlet-role-green-fill:#222127;--chartlet-role-amber:#8f8a80;--chartlet-role-amber-fill:#222127;--chartlet-role-teal:#8f8a80;--chartlet-role-teal-fill:#222127;--chartlet-role-violet:#c9c4b8;--chartlet-role-violet-fill:#222127;--chartlet-role-gray:#8f8a80;--chartlet-role-gray-fill:#222127;--chartlet-role-red:#f08a7e;--chartlet-role-red-fill:#2d1f1e}";

/// What the diagrams change in the editorial look: neutral boxes of every kind, hairline
/// outlines and lines, no shadows, the accent for the main path only, type tags, number badges in
/// ink, and the labels of edges and messages on a mask in the color of the paper, without a
/// border.
pub(super) const DIAGRAM: &str = ".chartlet-look-editorial .chartlet-role-blue,.chartlet-look-editorial .chartlet-role-green,.chartlet-look-editorial .chartlet-role-amber,.chartlet-look-editorial .chartlet-role-teal,.chartlet-look-editorial .chartlet-role-violet,.chartlet-look-editorial .chartlet-role-gray,.chartlet-look-editorial .chartlet-role-red{fill:var(--chartlet-node);stroke:var(--chartlet-zero)}.chartlet-look-editorial .chartlet-flow-node{stroke-width:1;rx:6px}.chartlet-look-editorial .chartlet-flow-start{stroke-width:1}.chartlet-look-editorial .chartlet-flow-end{stroke-width:2}.chartlet-look-editorial .chartlet-flow-inner{stroke:var(--chartlet-zero)}.chartlet-look-editorial .chartlet-flow-edge{stroke:var(--chartlet-zero);stroke-width:1}.chartlet-look-editorial .chartlet-flow-main{stroke:var(--chartlet-accent);stroke-width:2}.chartlet-look-editorial .chartlet-flow-group{fill:none;stroke:var(--chartlet-zero);stroke-width:1;stroke-dasharray:3 3;rx:8px}.chartlet-look-editorial .chartlet-diagram-shadow{display:none}.chartlet-look-editorial .chartlet-diagram-chip{fill:var(--chartlet-background);stroke:none;rx:2px}.chartlet-look-editorial .chartlet-diagram-badge{fill:var(--chartlet-text);stroke:var(--chartlet-background)}.chartlet-look-editorial .chartlet-diagram-badge-text{fill:var(--chartlet-background)}.chartlet-look-editorial .chartlet-diagram-tag{fill:var(--chartlet-background);stroke:var(--chartlet-zero);stroke-width:1;rx:3px}.chartlet-look-editorial .chartlet-diagram-tag-text{font-size:9px;font-weight:600;letter-spacing:.5px;fill:var(--chartlet-text)}.chartlet-look-editorial .chartlet-seq-box{stroke-width:1;rx:6px}.chartlet-look-editorial .chartlet-seq-message{stroke:var(--chartlet-zero);stroke-width:1}.chartlet-look-editorial .chartlet-seq-activation{stroke:var(--chartlet-zero)}.chartlet-look-editorial .chartlet-seq-frame{rx:8px}.chartlet-look-editorial .chartlet-state{rx:8px}.chartlet-look-editorial .chartlet-state-inner{stroke:var(--chartlet-zero);rx:6px}.chartlet-look-editorial .chartlet-arch-head{fill:var(--chartlet-node);stroke:var(--chartlet-zero)}";

/// The technical text of the five diagram families: sublabels, edge and message labels, tags,
/// members, cardinalities and frame names are set in monospace. Names stay in the sans font.
pub(super) const MONO: &str = ".chartlet-look-editorial .chartlet-flow-sublabel,.chartlet-look-editorial .chartlet-flow-group-label,.chartlet-look-editorial .chartlet-flow-card,.chartlet-look-editorial .chartlet-diagram-chip-text,.chartlet-look-editorial .chartlet-diagram-tag-text,.chartlet-look-editorial .chartlet-class-member,.chartlet-look-editorial .chartlet-arch-interface,.chartlet-look-editorial .chartlet-seq-sublabel,.chartlet-look-editorial .chartlet-seq-tag,.chartlet-look-editorial .chartlet-seq-guard{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,\"JetBrains Mono\",\"DejaVu Sans Mono\",monospace}";
